package com.pousada;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.junit.jupiter.api.*;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.LocalDate;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

@Testcontainers
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class ApplicationIT {
    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:18")
        .withDatabaseName("pousada_test")
        .withUsername("test")
        .withPassword("test");

    private static Thread serverThread;
    private static final int PORT = 7071;
    private static final String BASE_URL = "http://localhost:" + PORT;
    private static final HttpClient client = HttpClient.newHttpClient();
    private static final ObjectMapper mapper = new ObjectMapper()
        .registerModule(new JavaTimeModule())
        .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);

    @BeforeAll
    static void setUp() throws InterruptedException {
        System.setProperty("DB_URL", postgres.getJdbcUrl());
        System.setProperty("DB_USER", postgres.getUsername());
        System.setProperty("DB_PASSWORD", postgres.getPassword());
        System.setProperty("PORT", String.valueOf(PORT));

        serverThread = new Thread(() -> Application.main(new String[]{}));
        serverThread.start();
        Thread.sleep(2000);
    }

    @Test
    @Order(1)
    void shouldGetRooms() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/rooms"))
            .GET()
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());
        assertTrue(response.body().contains("101"));
        assertTrue(response.body().contains("STANDARD"));
        assertTrue(response.body().contains("249.90"));
    }

    @Test
    @Order(2)
    void shouldCreateReservation() throws IOException, InterruptedException {
        String requestBody = """
            {
                "roomNumber": "101",
                "guestName": "João Silva",
                "guestEmail": "joao@example.com",
                "guestCpf": "12345678901",
                "checkIn": "2027-07-10",
                "checkOut": "2027-07-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(201, response.statusCode());
        assertTrue(response.body().contains("João Silva"));
        assertTrue(response.body().contains("PENDING"));
        assertTrue(response.body().contains("599.76"));
    }

    @Test
    @Order(3)
    void shouldCalculateNonRefundableDiscount() throws IOException, InterruptedException {
        String requestBody = """
            {
                "roomNumber": "201",
                "guestName": "Maria Santos",
                "guestEmail": "maria@example.com",
                "guestCpf": "98765432109",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "NON_REFUNDABLE"
            }
            """;

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(201, response.statusCode());
        var body = mapper.readValue(response.body(), Map.class);
        assertEquals(779.80, (Double) body.get("subtotal"));
        assertEquals(116.97, (Double) body.get("discount"));
        assertEquals(662.83, (Double) body.get("total"));
    }

    @Test
    @Order(4)
    void shouldRejectOvercapacity() throws IOException, InterruptedException {
        String requestBody = """
            {
                "roomNumber": "101",
                "guestName": "Pedro Costa",
                "guestEmail": "pedro@example.com",
                "guestCpf": "11122233344",
                "checkIn": "2027-08-01",
                "checkOut": "2027-08-03",
                "guests": 5,
                "ratePlan": "STANDARD"
            }
            """;

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(422, response.statusCode());
        assertTrue(response.body().contains("CAPACITY_EXCEEDED"));
    }

    @Test
    @Order(5)
    void shouldRejectConflictingReservation() throws IOException, InterruptedException {
        String requestBody = """
            {
                "roomNumber": "101",
                "guestName": "Ana Lima",
                "guestEmail": "ana@example.com",
                "guestCpf": "55566677788",
                "checkIn": "2027-07-11",
                "checkOut": "2027-07-13",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(409, response.statusCode());
        assertTrue(response.body().contains("ROOM_UNAVAILABLE"));
    }

    @Test
    @Order(6)
    void shouldConfirmReservation() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations/1/confirmation"))
            .POST(HttpRequest.BodyPublishers.noBody())
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());
        assertTrue(response.body().contains("CONFIRMED"));
        assertTrue(response.body().contains("\"amountPaid\":599.76"));
    }

    @Test
    @Order(7)
    void shouldSendConfirmationEmail() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/messages"))
            .GET()
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());
        assertTrue(response.body().contains("EMAIL"));
        assertTrue(response.body().contains("joao@example.com"));
        assertTrue(response.body().contains("Reserva confirmada"));
        assertTrue(response.body().contains("João Silva"));
    }

    @Test
    @Order(8)
    void shouldCheckIn() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations/1/check-in"))
            .POST(HttpRequest.BodyPublishers.noBody())
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());
        assertTrue(response.body().contains("CHECKED_IN"));
    }

    @Test
    @Order(9)
    void shouldCheckOut() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations/1/check-out"))
            .POST(HttpRequest.BodyPublishers.noBody())
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());
        assertTrue(response.body().contains("Comprovante de reserva"));
        assertTrue(response.body().contains("João Silva"));
    }

    @Test
    @Order(10)
    void shouldGetDocument() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations/1/document"))
            .GET()
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());
        assertTrue(response.body().contains("Comprovante de reserva"));
