import com.pousada.domain.Room;
import com.pousada.domain.RoomType;
import com.pousada.repository.Database;
import com.pousada.repository.RoomRepository;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class DatabaseIT {
    @Test
    void shouldInitializeAndSaveRoom() {
        Database database = new Database(
            "jdbc:h2:mem:test1;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE",
            "sa",
            ""
        );
        database.initializeSchema();

        RoomRepository roomRepository = new RoomRepository(database);

        Room room = new Room("101", RoomType.STANDARD);
        assertDoesNotThrow(() -> roomRepository.save(room));

        var rooms = roomRepository.findAll();
        assertEquals(1, rooms.size());
        assertEquals("101", rooms.get(0).getNumber());
    }
}

